"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["49145"],{58289(e,t,n){n.d(t,{Ay:()=>r,RM:()=>s});var o=n(74848),i=n(28453);let s=[];function a(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"a-decline-worth-applauding",children:"A Decline Worth Applauding"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2007/9/7 15:29:09"}),"\n"]}),"\n",(0,o.jsxs)("div",{style:{color:"#FF0000",fontWeight:"500"},children:[(0,o.jsx)(t.p,{children:"Today's reserve requirement ratio hike isn't a big deal in itself, but Elder Shang's risk warning shouldn't be taken lightly. Recently the newspapers have been running risk warnings every day, but Elder Shang is someone who strongly advocates market-based regulation. If it weren't for this elder, the May 30th incident would probably have long since been forgotten, because there would have already been something newer for everyone to spit at."}),(0,o.jsx)(t.p,{children:"Therefore, one should be decent. When someone is bearing the burden, you can't be too ungracious about it. Otherwise, if good people can't do their job, market regulation fails, then it becomes policy regulation\u2014but for some ungracious garbage, they'll still spew filth regardless."}),(0,o.jsx)(t.p,{children:"When the market self-regulates, the adjustment is limited and system-controllable. When the market doesn't self-regulate and you need artificial rain, then only heaven knows what will happen."}),(0,o.jsx)(t.p,{children:"Sometimes, when the market cooperates a little, the forces advocating market regulation can exert greater influence. This is so obvious, but in the face of profit, many people lose their heads. So, some things are better left to fate\u2014better to not calculate at all."}),(0,o.jsx)(t.p,{children:"Technically, if a somewhat larger-level oscillation emerges here, treat it as hub oscillation. For those who can't read the charts, the mid-term reference is the 5-week moving average. Since the rise from 3,600 points, this line has never been touched\u2014it's the simplest litmus test for whether this phase of the rally has ended and entered a larger correction."}),(0,o.jsx)(t.p,{children:"On individual stocks, stocks like 000938 that held above the May 30th highs and continued to strengthen\u2014this technical pattern will be replicated in other stocks. This ID has commented on this stock many times before. The only thing to add is that in an era where Tsinghua far outshines Peking University, this ID can only very economically suck up to Tsinghua. If you won't even suck up to Tsinghua, you really don't want to stay in China, do you?"}),(0,o.jsx)(t.p,{children:"Stocks this ID has mentioned still require following through to the end. 600375\u2014I mentioned it at 7 yuan, and that's when this ID got in too. The reason was already told to everyone: it has new products with costs much lower than Sany's. This ID sent people for on-site investigation; the person sent back reported that they even personally touched the newly imported steel plates. But this company\u2014this ID doesn't have great confidence in it, specifically because of its related-party transaction issues. Moreover, importantly, one of its huge affiliated companies actually took over what 600375 had developed, due to more private interests embedded within. The new thing might ultimately be listed directly under a separate entity to maximize private gains. If this were properly placed into 375 as it should be, 375 should have already been above 50 yuan. But with these shenanigans, this kind of company\u2014this ID's confidence really isn't there."}),(0,o.jsx)(t.p,{children:"Enough said. Every weekend, this ID gets nauseated by stocks."}),(0,o.jsx)(t.p,{children:"Signing off. Everyone go do whatever you should be doing, and forget about stocks."}),(0,o.jsx)(t.p,{children:"Goodbye."})]})]})}function r(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(a,{...e})}):a(e)}},7376(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>c,assets:()=>h});var o=JSON.parse('{"id":"economics/goodslump","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/economics/goodslump.md","sourceDirName":"economics","slug":"/economics/goodslump","permalink":"/en/economics/goodslump","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"goodslump","title":"","hide_table_of_contents":true,"sidebar_label":"A decline worth applauding (2007/9/7 15:29:09)"},"sidebar":"economicsSidebar","previous":{"title":"CCB leads the market forward (2007/9/6 15:55:55)","permalink":"/en/economics/ccb"},"next":{"title":"Market continues entering the pre-530 vicious cycle (2007/9/10 15:58:37)","permalink":"/en/economics/strangecircle"}}'),i=n(74848),s=n(28453),a=n(58289);let r={id:"goodslump",title:"",hide_table_of_contents:!0,sidebar_label:"A decline worth applauding (2007/9/7 15:29:09)"},l,h={},c=[...a.RM];function d(e){return(0,i.jsx)(a.Ay,{})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var o=n(96540);let i={},s=o.createContext(i);function a(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);